  // including avoiding the quantization of an unnecessary sRGB round trip.
  if (u_relief <= 0.00001 && u_distortion * u_refraction <= 0.00001
      && u_blur <= 0.00001 && u_roughness <= 0.00001
      && u_reflection <= 0.00001 && u_grain <= 0.00001) {
